(window.SOAL_PART = window.SOAL_PART || {})["tes_gambar"] = {"nama": "Tes Gambar & Visual", "soal": [
    {"id": "tg1", "pertanyaan": "Matriks 3x3 berikut mengikuti pola tertentu. Angka yang menggantikan '?' adalah...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["20", "25", "15", "18"], "jawaban": 0, "pembahasan": "JAWABAN: 20\nBaca per kolom: kolom 1 × 2 = kolom 2, kolom 1 × 4 = kolom 3. Baris 3 berisi 5 dan 10, maka kolom 3 = 5 × 4 = 20. Cek baris lain: 2 → 4 → 8 dan 3 → 6 → 12 (benar).\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "matriks"},
    {"id": "tg2", "pertanyaan": "Gambar berikut menunjukkan pola deret bentuk. Gambar ke-5 yang benar adalah...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Bintang", "Lingkaran", "Segitiga", "Persegi"], "jawaban": 1, "pembahasan": "JAWABAN: Lingkaran\nPola berulang 3 bentuk: persegi (gambar 1) → lingkaran (2) → segitiga (3) → kembali persegi (4) → lingkaran (5). Jadi gambar ke-5 adalah lingkaran.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola"},
    {"id": "tg3", "pertanyaan": "Perhatikan deret angka bergambar berikut. Berapa nilai '?'", "gambar": "data:image/svg+xml;base64,", "pilihan": ["2", "3", "0", "1"], "jawaban": 3, "pembahasan": "JAWABAN: 1\nTRIK CEPAT: Pola deret kuadrat turun: 4²=16, 3²=9, 2²=4, 1²=?=1. Jawaban: 1. CARA INGAT: lihat sub-teks di bawah gambar yang menunjukkan akar dari setiap angka.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola"},
    {"id": "tg4", "pertanyaan": "Sebuah kubus diputar 90° ke kanan (searah jarum jam dilihat dari atas). Sisi yang tadinya menghadap ke DEPAN sekarang menghadap ke...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Belakang", "Kanan", "Kiri", "Atas"], "jawaban": 2, "pembahasan": "JAWABAN: Kiri\nPutar 90° searah jarum jam: depan → kiri, kanan → depan, belakang → kanan, kiri → belakang. Jadi sisi depan berpindah ke sisi kiri. Sisi atas dan bawah tidak berubah.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "topik": "cermin-rotasi"},
    {"id": "tg5", "pertanyaan": "Perhatikan pola hubungan gambar. Lingkaran besar berisi lingkaran kecil. Persegi besar berisi...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Persegi kecil", "Bintang kecil", "Lingkaran kecil", "Segitiga kecil"], "jawaban": 0, "pembahasan": "JAWABAN: Persegi kecil\nPolanya: bentuk besar berisi bentuk kecil yang JENISNYA SAMA. Lingkaran besar → lingkaran kecil, maka persegi besar → persegi kecil.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "analogi-gambar"},
    {"id": "tg6", "pertanyaan": "Sebuah persegi dibagi oleh satu garis diagonal. Berapa banyak segitiga yang terbentuk?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["1", "2", "3", "4"], "jawaban": 1, "pembahasan": "JAWABAN: 2\nSatu garis diagonal membagi persegi menjadi 2 segitiga sama besar. Bandingkan: jika dua diagonal digambar (bersilangan), terbentuk 4 segitiga.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambarPembahasan": "data:image/svg+xml;base64,"},
    {"id": "tg7", "pertanyaan": "Pola angka dalam gambar: kotak kiri=12, kotak tengah=7, kotak kanan=?. Pola: selisih beraturan.", "gambar": "data:image/svg+xml;base64,", "pilihan": ["3", "0", "1", "2"], "jawaban": 3, "pembahasan": "JAWABAN: 2\nTRIK CEPAT: Selisih konstan -5. 12-5=7, 7-5=2. Jawaban: 2. CARA: identifikasi pola (+/-/x/÷) antara kotak pertama dan kedua, lalu terapkan ke kotak kedua dan ketiga.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "deret-pola"},
    {"id": "tg8", "pertanyaan": "Gambar berikut menunjukkan cermin vertikal. Bayangan yang benar dari huruf 'P' di cermin adalah...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["P terbalik 180°", "P normal", "P terbalik horizontal (q)", "P terbalik vertikal (d)"], "jawaban": 2, "pembahasan": "JAWABAN: P terbalik horizontal (q)\nTRIK CEPAT: Cermin vertikal = flip horizontal. Huruf P akan terlihat seperti huruf q (busur di kiri, batang di kanan). CARA MUDAH: bayangkan kamu memegang kertas bertuliskan P dan menerawangnya ke cahaya — itulah bayangannya.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "topik": "cermin-rotasi"},
    {"id": "tg9", "pertanyaan": "Dalam gambar, berapa banyak kubus yang tersusun? (tampak dari depan)", "gambar": "data:image/svg+xml;base64,", "pilihan": ["6", "7", "8", "5"], "jawaban": 0, "pembahasan": "JAWABAN: 6\nTRIK CEPAT: Hitung kubus tampak depan baris per baris. Baris bawah: 3 kubus. Baris tengah: 2 kubus. Baris atas: 1 kubus. Total: 6. CARA: scan dari bawah ke atas, hitung per baris, jumlahkan.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun"},
    {"id": "tg10", "pertanyaan": "Pola matriks 2x2: sudut kiri atas=bintang besar, kanan atas=bintang kecil, kiri bawah=lingkaran besar. Kanan bawah=?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Segitiga kecil", "Lingkaran kecil", "Bintang kecil", "Persegi kecil"], "jawaban": 1, "pembahasan": "JAWABAN: Lingkaran kecil\nTRIK CEPAT: Pola matriks: baris 1 = bintang besar→kecil (ukuran turun). Baris 2 = lingkaran besar→?. Pola kolom: kolom 1 = besar, kolom 2 = kecil. Jadi kanan bawah = lingkaran KECIL. CARA: cari pola baris DAN kolom, ambil yang konsisten.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "matriks"},
    {"id": "tg11", "pertanyaan": "Deret gambar: lingkaran dengan 1 titik, lingkaran dengan 2 titik, lingkaran dengan 3 titik. Gambar ke-4 memiliki berapa titik?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["5", "6", "3", "4"], "jawaban": 3, "pembahasan": "JAWABAN: 4\nTRIK CEPAT: Pola jumlah titik = nomor gambar. Gambar ke-4 = 4 titik. CARA: hitung langsung elemen di setiap gambar, cari polanya.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "deret-pola"},
    {"id": "tg12", "pertanyaan": "Matriks 3x3: baris 1 = segitiga, lingkaran, persegi. Baris 2 = lingkaran, persegi, segitiga. Baris 3 = persegi, segitiga,?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Persegi", "Bintang", "Lingkaran", "Segitiga"], "jawaban": 2, "pembahasan": "JAWABAN: Lingkaran\nTRIK CEPAT: Pola Latin Square — setiap bentuk muncul 1x per baris dan kolom. Baris 3: persegi, segitiga, → lingkaran. CARA: cek bentuk yang belum muncul di baris/kolom terakhir.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "matriks"},
    {"id": "tg13", "pertanyaan": "Gambar berikut menunjukkan pola pertumbuhan kotak: 1 kotak, 4 kotak, 9 kotak. Berapa kotak pada gambar ke-5?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["25", "30", "16", "20"], "jawaban": 0, "pembahasan": "JAWABAN: 25\nTRIK CEPAT: Pola kuadrat: 1², 2², 3², 4², 5². Gambar ke-5 = 5² = 25. CARA: identifikasi pola pertumbuhan kuadrat sempurna.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola"},
    {"id": "tg14", "pertanyaan": "Bayangan cermin dari bentuk 'F' di cermin vertikal adalah...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["F normal", "F terbalik horizontal", "F terbalik vertikal", "F terbalik 180°"], "jawaban": 1, "pembahasan": "JAWABAN: F terbalik horizontal\nTRIK CEPAT: Cermin vertikal = flip horizontal. Huruf F akan terlihat seperti F terbalik horizontal (garis vertikal di kanan, tiga garis horizontal ke kiri).\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "topik": "cermin-rotasi"},
    {"id": "tg15", "pertanyaan": "Deret: lingkaran 1/4 hitam, lingkaran 1/2 hitam, lingkaran 3/4 hitam. Gambar berikutnya...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Kembali ke 1/4", "Tetap 3/4", "1/8 hitam", "Penuh hitam"], "jawaban": 3, "pembahasan": "JAWABAN: Penuh hitam\nTRIK CEPAT: Pola bertambah 1/4 setiap gambar. 1/4, 1/2, 3/4, 4/4 = penuh. CARA: hitung fraksi yang bertambah.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola"},
    {"id": "tg16", "pertanyaan": "Berapa banyak segitiga dalam gambar berikut? (segitiga besar dengan 2 garis sejajar alas)", "gambar": "data:image/svg+xml;base64,", "pilihan": ["5", "6", "3", "4"], "jawaban": 2, "pembahasan": "JAWABAN: 3\nHitung dari puncak: (1) segitiga puncak sampai garis atas, (2) puncak sampai garis bawah, (3) seluruh segitiga besar. Daerah antara dua garis berbentuk TRAPESIUM, bukan segitiga. Jadi total 3 segitiga.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun"},
    {"id": "tg17", "pertanyaan": "Pola rotasi: segitiga atas, segitiga kanan, segitiga bawah. Gambar berikutnya adalah...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Segitiga kiri", "Segitiga kanan", "Segitiga bawah", "Segitiga atas"], "jawaban": 0, "pembahasan": "JAWABAN: Segitiga kiri\nTRIK CEPAT: Pola rotasi searah jarum jam: atas → kanan → bawah → kiri → atas. Setelah bawah = kiri. CARA: ikuti arah rotasi.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "topik": "cermin-rotasi"},
    {"id": "tg18", "pertanyaan": "Gambar kubus yang tampak dari atas adalah...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Trapesium", "Persegi", "Lingkaran", "Segitiga"], "jawaban": 1, "pembahasan": "JAWABAN: Persegi\nTRIK CEPAT: Kubus dari atas selalu terlihat sebagai persegi (2D). CARA: bayangkan melihat kotak dari atas.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola"},
    {"id": "tg19", "pertanyaan": "Pola: lingkaran besar berisi lingkaran kecil, persegi besar berisi persegi kecil, segitiga besar berisi?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Bintang kecil", "Lingkaran kecil", "Persegi kecil", "Segitiga kecil"], "jawaban": 3, "pembahasan": "JAWABAN: Segitiga kecil\nTRIK CEPAT: Pola analogi: bentuk besar berisi bentuk kecil yang SAMA jenisnya. Segitiga besar → segitiga kecil. CARA: identifikasi hubungan LUAR-DALAM.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "analogi-gambar"},
    {"id": "tg20", "pertanyaan": "Deret angka bergambar: 4 kotak, 9 kotak, 16 kotak. Berapa kotak pada gambar ke-4?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["36", "20", "25", "30"], "jawaban": 2, "pembahasan": "JAWABAN: 25\nTRIK CEPAT: Pola kuadrat: 2², 3², 4², 5². Gambar ke-4 = 5² = 25. CARA: identifikasi pola pertumbuhan kuadrat.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola"},
    {"id": "tg21", "pertanyaan": "Gambar jam menunjukkan pukul 3:00. Sudut antara jarum jam dan menit adalah...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["90°", "30°", "45°", "60°"], "jawaban": 0, "pembahasan": "JAWABAN: 90°\nTRIK CEPAT: Jam 3:00 = jarum jam di angka 3, menit di angka 12. Sudut = 90°. CARA: hitung sudut antara angka 12 dan 3.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola"},
    {"id": "tg22", "pertanyaan": "Pola: 1 lingkaran, 3 lingkaran, 5 lingkaran. Gambar ke-4 memiliki berapa lingkaran?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["6", "7", "8", "9"], "jawaban": 1, "pembahasan": "JAWABAN: 7\nTRIK CEPAT: Pola ganjil: 1, 3, 5, 7. Gambar ke-4 = 7 lingkaran. CARA: identifikasi pola bilangan ganjil.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "deret-pola"},
    {"id": "tg23", "pertanyaan": "Bayangan dari bentuk 'R' di cermin horizontal (di bawah) adalah...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["R terbalik horizontal", "R terbalik 180°", "R normal", "R terbalik vertikal"], "jawaban": 3, "pembahasan": "JAWABAN: R terbalik vertikal\nTRIK CEPAT: Cermin horizontal (di bawah) = flip vertikal. Huruf R akan terlihat seperti R terbalik vertikal.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "topik": "cermin-rotasi"},
    {"id": "tg24", "pertanyaan": "Berapa banyak persegi dalam gambar 3x3 grid?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["9", "13", "14", "16"], "jawaban": 2, "pembahasan": "JAWABAN: 14\nTRIK CEPAT: 1x1 = 9, 2x2 = 4, 3x3 = 1. Total = 14. CARA: hitung semua ukuran persegi dari kecil ke besar.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun"},
    {"id": "tg25", "pertanyaan": "Sebuah kubus memiliki berapa sisi (bidang)?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["6", "8", "12", "4"], "jawaban": 0, "pembahasan": "JAWABAN: 6\nKubus punya 6 sisi berbentuk persegi, 8 titik sudut, dan 12 rusuk.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "hitung-bangun"},
    {"id": "tg26", "pertanyaan": "Gambar menunjukkan pola: kotak besar di pojok kiri atas, kotak besar di pojok kanan atas, kotak besar di pojok kiri bawah. Kotak besar berikutnya di...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Pojok kanan atas", "Pojok kanan bawah", "Pojok kiri atas", "Tengah"], "jawaban": 1, "pembahasan": "JAWABAN: Pojok kanan bawah\nTRIK CEPAT: Pola pojok berputar: kiri atas → kanan atas → kiri bawah → kanan bawah. Setelah kiri bawah = kanan bawah. CARA: ikuti pola rotasi pojok.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "deret-pola"},
    {"id": "tg27", "pertanyaan": "Deret: lingkaran dengan 2 garis, lingkaran dengan 4 garis, lingkaran dengan 6 garis. Gambar berikutnya...", "gambar": "data:image/svg+xml;base64,", "pilihan": ["9 garis", "10 garis", "7 garis", "8 garis"], "jawaban": 3, "pembahasan": "JAWABAN: 8 garis\nTRIK CEPAT: Pola bertambah 2 garis setiap gambar. 2, 4, 6, 8. CARA: hitung garis yang bertambah.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola"},
    {"id": "tg28", "pertanyaan": "Pola: persegi besar berisi segitiga, segitiga besar berisi lingkaran, lingkaran besar berisi?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["Lingkaran", "Bintang", "Persegi", "Segitiga"], "jawaban": 2, "pembahasan": "JAWABAN: Persegi\nTRIK CEPAT: Pola siklus: persegi→segitiga→lingkaran→persegi. Lingkaran besar berisi persegi. CARA: ikuti siklus bentuk.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "analogi-gambar"},
    {"id": "tg29", "pertanyaan": "Berapa banyak segitiga dalam gambar segitiga besar dengan 1 garis dari titik tengah alas ke puncak?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["3", "4", "1", "2"], "jawaban": 0, "pembahasan": "JAWABAN: 3\nTRIK CEPAT: 2 segitiga kecil + 1 segitiga besar = 3. CARA: hitung dari kecil ke besar.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambarPembahasan": "data:image/svg+xml;base64,"},
    {"id": "tg30", "pertanyaan": "Pola: 1 bintang, 2 bintang, 4 bintang. Gambar ke-4 memiliki berapa bintang?", "gambar": "data:image/svg+xml;base64,", "pilihan": ["7", "8", "16", "6"], "jawaban": 1, "pembahasan": "JAWABAN: 8\nTRIK CEPAT: Pola x2: 1, 2, 4, 8. Gambar ke-4 = 8 bintang. CARA: identifikasi pola perkalian.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "deret-pola"},
    {"id": "tg31", "pertanyaan": "Perhatikan gambar berikut. Sebuah deret bentuk tersusun berulang dengan pola: lingkaran, segitiga, persegi, lingkaran, segitiga, persegi, dan seterusnya. Bentuk apakah yang muncul pada urutan ke-7?", "pilihan": ["Segitiga", "Persegi", "Belah ketupat", "Lingkaran"], "jawaban": 3, "pembahasan": "JAWABAN: Lingkaran\nPola berulang setiap tiga bentuk. Urutan ke-7 jatuh pada awal siklus ketiga, yaitu lingkaran.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "gambar": "data:image/svg+xml;base64,", "topik": "deret-pola"},
    {"id": "tg32", "pertanyaan": "Perhatikan gambar berikut. Sebuah tanda panah diputar searah jarum jam mengikuti arah: atas, kanan, bawah. Ke arah manakah panah menghadap pada putaran berikutnya?", "pilihan": ["Bawah", "Atas", "Kiri", "Kanan"], "jawaban": 2, "pembahasan": "JAWABAN: Kiri\nUrutan putaran searah jarum jam adalah atas, kanan, bawah, lalu kiri. Setelah bawah, arah berikutnya adalah kiri.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "gambar": "data:image/svg+xml;base64,", "topik": "cermin-rotasi"},
    {"id": "tg33", "pertanyaan": "Perhatikan gambar berikut. Huruf \"d\" dicerminkan secara horizontal (dibalik kiri-kanan). Huruf apakah yang tampak sebagai hasil cerminnya?", "pilihan": ["b", "d", "p", "q"], "jawaban": 0, "pembahasan": "JAWABAN: b\nPencerminan horizontal membalik sisi kiri dan kanan huruf. Huruf d yang dicerminkan akan tampak seperti huruf b.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "gambar": "data:image/svg+xml;base64,", "topik": "cermin-rotasi"},
    {"id": "tg34", "pertanyaan": "Perhatikan gambar berikut. Huruf \"p\" dicerminkan secara vertikal (dibalik atas-bawah). Huruf apakah yang tampak sebagai hasil cerminnya?", "pilihan": ["p", "b", "q", "d"], "jawaban": 1, "pembahasan": "JAWABAN: b\nPencerminan vertikal membalik sisi atas dan bawah huruf. Huruf p yang dicerminkan akan tampak seperti huruf b.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "gambar": "data:image/svg+xml;base64,", "topik": "cermin-rotasi"},
    {"id": "tg35", "pertanyaan": "Perhatikan gambar berikut. Sebuah persegi digambar dua garis diagonal dari sudut ke sudut. Berapa banyak segitiga yang terbentuk di dalamnya?", "pilihan": ["2", "6", "8", "4"], "jawaban": 3, "pembahasan": "JAWABAN: 4\nDua garis diagonal yang saling bersilangan membagi persegi menjadi empat bagian sama besar. Setiap bagian berbentuk segitiga, sehingga total ada empat segitiga.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "gambar": "data:image/svg+xml;base64,", "topik": "hitung-bangun"},
    {"id": "tg36", "pertanyaan": "Perhatikan gambar berikut. Sebuah kisi persegi berukuran 2 × 2 terdiri atas empat persegi kecil sama besar. Berapa jumlah seluruh persegi yang dapat dihitung, termasuk persegi besar yang membungkus keempatnya?", "pilihan": ["9", "4", "5", "6"], "jawaban": 2, "pembahasan": "JAWABAN: 5\nTerdapat empat persegi kecil ditambah satu persegi besar yang membungkus semuanya. Jadi jumlah seluruh persegi adalah lima.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "gambar": "data:image/svg+xml;base64,", "topik": "matriks", "gambarPembahasan": "data:image/svg+xml;base64,"},
    {"id": "tg37", "pertanyaan": "Perhatikan gambar berikut. Pola titik bertambah satu setiap urutan: 1 titik, 2 titik, 3 titik, 4 titik, dan seterusnya. Berapa jumlah titik pada urutan ke-5?", "pilihan": ["5", "7", "4", "6"], "jawaban": 0, "pembahasan": "JAWABAN: 5\nJumlah titik bertambah satu pada setiap urutan. Pada urutan kelima jumlah titik adalah lima.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "gambar": "data:image/svg+xml;base64,", "topik": "deret-pola"},
    {"id": "tg38", "pertanyaan": "Perhatikan gambar berikut. Jumlah kotak pada suatu pola bertambah dua setiap langkah: 1 kotak, 3 kotak, 5 kotak, 7 kotak. Berapa jumlah kotak pada urutan ke-5?", "pilihan": ["11", "9", "7", "8"], "jawaban": 1, "pembahasan": "JAWABAN: 9\nPola bertambah dua setiap langkah, sehingga setelah 7 kotak berikutnya adalah 9 kotak.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "gambar": "data:image/svg+xml;base64,", "topik": "deret-pola"},
    {"id": "tg39", "pertanyaan": "Perhatikan gambar berikut. Lingkaran diwarnai berselang dua warna: merah, biru, merah, biru, dan seterusnya. Warna apakah lingkaran ke-9?", "pilihan": ["Biru", "Hijau", "Kuning", "Merah"], "jawaban": 3, "pembahasan": "JAWABAN: Merah\nUrutan ganjil berwarna merah dan urutan genap berwarna biru. Lingkaran ke-9 adalah urutan ganjil sehingga berwarna merah.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "gambar": "data:image/svg+xml;base64,", "topik": "deret-pola"},
    {"id": "tg40", "pertanyaan": "Perhatikan gambar berikut. Barisan kotak diarsir berselang: kotak pertama diarsir, kedua polos, ketiga diarsir, keempat polos, dan seterusnya. Bagaimana keadaan kotak ke-8?", "pilihan": ["Berwarna hitam penuh", "Diarsir", "Polos", "Bergaris silang"], "jawaban": 2, "pembahasan": "JAWABAN: Polos\nUrutan ganjil diarsir dan urutan genap polos. Kotak ke-8 adalah urutan genap sehingga polos.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "gambar": "data:image/svg+xml;base64,", "topik": "deret-pola"},
    {"id": "tg41", "pertanyaan": "Perhatikan gambar berikut. Sebuah persegi besar berisi lingkaran kecil di tengahnya. Mengikuti pola analogi yang sama, jika bentuk luarnya adalah lingkaran besar, bentuk kecil apakah yang berada di dalamnya?", "pilihan": ["Persegi kecil", "Oval kecil", "Lingkaran kecil", "Segitiga kecil"], "jawaban": 0, "pembahasan": "JAWABAN: Persegi kecil\nPola analogi menukar jenis bentuk dalam dan luar. Jika bentuk luar menjadi lingkaran besar, maka bentuk dalam menjadi persegi kecil.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "gambar": "data:image/svg+xml;base64,", "topik": "analogi-gambar"},
    {"id": "tg42", "pertanyaan": "Perhatikan gambar berikut. Pasangan pertama menunjukkan lingkaran besar berisi lingkaran kecil di dalamnya. Mengikuti hubungan yang sama, jika bentuk luar pada pasangan kedua adalah persegi besar, bentuk apakah yang tepat berada di dalamnya?", "pilihan": ["Oval kecil", "Persegi kecil", "Lingkaran kecil", "Segitiga kecil"], "jawaban": 1, "pembahasan": "JAWABAN: Persegi kecil\nHubungannya adalah bentuk dalam sama dengan bentuk luar namun berukuran kecil. Karena bentuk luar persegi besar, maka bentuk dalamnya persegi kecil.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "gambar": "data:image/svg+xml;base64,", "topik": "analogi-gambar"},
    {"id": "tg43", "pertanyaan": "Perhatikan gambar berikut. Pada matriks 3x3, sebuah titik bergerak membentuk garis diagonal dari sel kiri-atas, lalu sel tengah, menuju sel kanan-bawah. Pada baris kedua, di sel manakah titik tersebut seharusnya berada?", "pilihan": ["Sel kiri", "Sel kanan", "Sel pojok atas", "Sel tengah"], "jawaban": 3, "pembahasan": "JAWABAN: Sel tengah\nGaris diagonal melewati sel tengah pada baris kedua. Maka titik berada di sel tengah.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "gambar": "data:image/svg+xml;base64,", "topik": "matriks"},
    {"id": "tg44", "pertanyaan": "Perhatikan gambar berikut. Deret angka pada matriks logika: 2, 4, 6, 8. Berapakah angka berikutnya?", "pilihan": ["14", "9", "10", "12"], "jawaban": 2, "pembahasan": "JAWABAN: 10\nDeret bertambah dua setiap langkah. Setelah 8, angka berikutnya adalah 10.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "gambar": "data:image/svg+xml;base64,", "topik": "matriks"},
    {"id": "tg45", "pertanyaan": "Perhatikan gambar berikut. Deret bentuk bergantian antara bentuk besar dan kecil dengan pola: lingkaran besar, lingkaran kecil, persegi besar, persegi kecil, dan seterusnya. Bentuk apakah yang muncul pada urutan ke-6?", "pilihan": ["Lingkaran kecil", "Lingkaran besar", "Persegi besar", "Persegi kecil"], "jawaban": 0, "pembahasan": "JAWABAN: Lingkaran kecil\nPola berulang setiap empat bentuk. Urutan keenam jatuh pada posisi kedua siklus, yaitu lingkaran kecil.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "gambar": "data:image/svg+xml;base64,", "topik": "deret-pola"},
    {"id": "tg46", "pertanyaan": "Perhatikan gambar berikut. Sebuah segitiga yang ujungnya mengarah ke atas diputar 90 derajat searah jarum jam. Ke arah manakah ujung segitiga sekarang mengarah?", "pilihan": ["Atas", "Kanan", "Kiri", "Bawah"], "jawaban": 1, "pembahasan": "JAWABAN: Kanan\nPutaran 90 derajat searah jarum jam menggeser arah atas menjadi kanan.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "gambar": "data:image/svg+xml;base64,", "topik": "cermin-rotasi"},
    {"id": "tg47", "pertanyaan": "Perhatikan gambar berikut. Angka '6' diputar 180° (dibalik atas-bawah sekaligus kiri-kanan). Angka berapakah yang tampak?", "pilihan": ["6", "8", "0", "9"], "jawaban": 3, "pembahasan": "JAWABAN: 9\nPutaran 180° membalik arah atas-bawah dan kiri-kanan sekaligus, sehingga angka 6 tampak seperti angka 9. Ingat: cermin kiri-kanan saja TIDAK menghasilkan angka 9.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "gambar": "data:image/svg+xml;base64,", "topik": "cermin-rotasi"},
    {"id": "tg48", "pertanyaan": "Perhatikan gambar berikut. Pola titik bertambah kelipatan tiga: 3 titik, 6 titik, 9 titik. Berapa jumlah titik pada urutan ke-4?", "pilihan": ["15", "10", "12", "11"], "jawaban": 2, "pembahasan": "JAWABAN: 12\nPola bertambah tiga setiap urutan. Setelah 9 titik, urutan keempat adalah 12 titik.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "gambar": "data:image/svg+xml;base64,", "topik": "deret-pola"},
    {"id": "tg49", "pertanyaan": "Perhatikan gambar berikut. Pada matriks 2x2, angka tersusun sebagai berikut: baris pertama 1 dan 2, baris kedua 3 dan tanda tanya. Jika pola penjumlahan bertambah satu setiap sel, angka berapakah yang mengisi tanda tanya?", "pilihan": ["4", "3", "2", "5"], "jawaban": 0, "pembahasan": "JAWABAN: 4\nAngka bertambah satu secara berurutan: 1, 2, 3, 4. Maka tanda tanya diisi angka 4.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "gambar": "data:image/svg+xml;base64,", "topik": "matriks"},
    {"id": "tg50", "pertanyaan": "Perhatikan gambar berikut. Bendera disusun berselang tiga warna: merah, kuning, hijau, merah, kuning, hijau, dan seterusnya. Warna apakah bendera ke-10?", "pilihan": ["Biru", "Merah", "Kuning", "Hijau"], "jawaban": 1, "pembahasan": "JAWABAN: Merah\nPola berulang setiap tiga warna. Urutan ke-10 jatuh pada posisi pertama siklus, yaitu merah.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "gambar": "data:image/svg+xml;base64,", "topik": "deret-pola"},
    {"id": "tg51", "pertanyaan": "Perhatikan gambar berikut. Berapa banyak persegi kecil pada gambar berikut?", "pilihan": ["7", "4", "5", "6"], "jawaban": 3, "pembahasan": "JAWABAN: 6\nHitung baris demi baris: 3 persegi di baris atas dan 3 di baris bawah, jadi 3 + 3 = 6 persegi.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg52", "pertanyaan": "Perhatikan gambar berikut. Berapa banyak segitiga yang terbentuk pada gambar berikut?", "pilihan": ["2", "3", "4", "6"], "jawaban": 2, "pembahasan": "JAWABAN: 4\nDua garis diagonal yang bersilangan membagi persegi menjadi 4 segitiga sama besar.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,", "gambarPembahasan": "data:image/svg+xml;base64,"},
    {"id": "tg53", "pertanyaan": "Perhatikan gambar berikut. Berapa banyak lingkaran pada gambar berikut?", "pilihan": ["7", "8", "5", "6"], "jawaban": 0, "pembahasan": "JAWABAN: 7\nHitung satu per satu: 3 lingkaran di baris atas dan 4 di baris bawah, total 3 + 4 = 7.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg54", "pertanyaan": "Perhatikan gambar berikut. Bangun yang memiliki lima sisi adalah...", "pilihan": ["Segitiga", "Segi lima", "Lingkaran", "Persegi"], "jawaban": 1, "pembahasan": "JAWABAN: Segi lima\nSegi lima (pentagon) punya 5 sisi; segitiga 3 sisi, persegi 4 sisi, lingkaran tidak punya sisi lurus.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg55", "pertanyaan": "Perhatikan gambar berikut. Deret gambar: 1 titik, 4 titik, 9 titik. Berapa titik pada gambar ke-4?", "pilihan": ["20", "12", "14", "16"], "jawaban": 3, "pembahasan": "JAWABAN: 16\nPolanya bilangan kuadrat: 1² = 1, 2² = 4, 3² = 9, maka gambar ke-4 = 4² = 16 titik.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "deret-pola", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg56", "pertanyaan": "Perhatikan gambar berikut. Huruf 'b' dicerminkan kiri-kanan (cermin tegak). Hasilnya adalah huruf...", "pilihan": ["q", "b", "d", "p"], "jawaban": 2, "pembahasan": "JAWABAN: d\nCermin kiri-kanan menukar sisi kiri dan kanan. Bulatan 'b' yang semula di kanan berpindah ke kiri, sehingga terbaca 'd'.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "topik": "cermin-rotasi", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg57", "pertanyaan": "Perhatikan gambar berikut. Huruf 'q' dicerminkan atas-bawah (cermin datar). Hasilnya adalah huruf...", "pilihan": ["b", "d", "p", "q"], "jawaban": 0, "pembahasan": "JAWABAN: b\nCermin atas-bawah menukar sisi atas dan bawah. Huruf 'q' berubah menjadi 'b'.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "topik": "cermin-rotasi", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg58", "pertanyaan": "Perhatikan gambar berikut. Segitiga dengan ujung menghadap KIRI diputar 90° berlawanan arah jarum jam. Ujungnya kini menghadap...", "pilihan": ["Atas", "Bawah", "Kanan", "Kiri"], "jawaban": 1, "pembahasan": "JAWABAN: Bawah\nPutaran 90° berlawanan arah jarum jam memindahkan arah: kiri → bawah (kanan → atas). Jadi ujungnya menghadap bawah.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "topik": "cermin-rotasi", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg59", "pertanyaan": "Perhatikan gambar berikut. Pola ukuran: kecil, sedang, besar, sedang. Gambar berikutnya berukuran...", "pilihan": ["Sedang", "Besar", "Sangat besar", "Kecil"], "jawaban": 3, "pembahasan": "JAWABAN: Kecil\nPola berulang tiga ukuran (kecil → sedang → besar), lalu kembali ke sedang dan berikutnya kecil. Jadi gambar ke-5 = kecil.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg60", "pertanyaan": "Perhatikan gambar berikut. Berapa banyak kubus yang menyusun gambar berikut (tampak dari depan)?", "pilihan": ["5", "6", "3", "4"], "jawaban": 2, "pembahasan": "JAWABAN: 3\nBaris bawah berisi 2 kubus dan baris atas 1 kubus, jadi total 3 kubus. Hitung per baris supaya tidak ada yang terlewat.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,", "gambarPembahasan": "data:image/svg+xml;base64,"},
    {"id": "tg61", "pertanyaan": "Perhatikan gambar berikut. Nama bangun pada gambar berikut adalah...", "pilihan": ["Segi enam", "Segi tujuh", "Segi delapan", "Segi lima"], "jawaban": 0, "pembahasan": "JAWABAN: Segi enam\nBangun dengan 6 sisi bernama segi enam (heksagon).\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg62", "pertanyaan": "Perhatikan gambar berikut. Panah berputar 90° searah jarum jam: atas, kanan, bawah, kiri. Gambar ke-5 mengarah ke...", "pilihan": ["Kiri", "Atas", "Kanan", "Bawah"], "jawaban": 1, "pembahasan": "JAWABAN: Atas\nSatu putaran penuh kembali ke posisi awal: setelah kiri, arah berikutnya kembali ke atas.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg63", "pertanyaan": "Perhatikan gambar berikut. Bangun yang BUKAN segi banyak (poligon) adalah...", "pilihan": ["Persegi", "Segi lima", "Segitiga", "Lingkaran"], "jawaban": 3, "pembahasan": "JAWABAN: Lingkaran\nPoligon dibatasi garis lurus. Lingkaran hanya punya satu sisi lengkung, jadi bukan poligon.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg64", "pertanyaan": "Perhatikan gambar berikut. Bangun pada gambar berikut memiliki berapa sisi?", "pilihan": ["8", "5", "6", "7"], "jawaban": 2, "pembahasan": "JAWABAN: 6\nHitung sisi satu per satu mengikuti arah jarum jam: ada 6 sisi, jadi bangun ini segi enam.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg65", "pertanyaan": "Perhatikan gambar berikut. Pola bertambah 4 kotak: 4, 8, 12 kotak. Berapa kotak pada gambar ke-4?", "pilihan": ["16", "18", "20", "14"], "jawaban": 0, "pembahasan": "JAWABAN: 16\nSelisihnya tetap 4: 12 + 4 = 16 kotak.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg66", "pertanyaan": "Perhatikan gambar berikut. Satu dari empat bagian lingkaran diwarnai. Jika ditambah satu bagian lagi, berapa bagian yang diwarnai?", "pilihan": ["1/4", "1/2", "3/4", "penuh"], "jawaban": 1, "pembahasan": "JAWABAN: 1/2\n1/4 + 1/4 = 2/4 = 1/2. Dua dari empat bagian sama dengan setengah lingkaran.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg67", "pertanyaan": "Perhatikan gambar berikut. Bangun yang memiliki simetri lipat paling banyak adalah...", "pilihan": ["Persegi panjang", "Persegi", "Segitiga sama sisi", "Lingkaran"], "jawaban": 3, "pembahasan": "JAWABAN: Lingkaran\nLingkaran punya simetri lipat tak terhingga (setiap garis melalui pusat). Persegi 4, segitiga sama sisi 3, persegi panjang 2.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "cermin-rotasi", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg68", "pertanyaan": "Perhatikan gambar berikut. Gambar berikut: segitiga besar di dalamnya terdapat segitiga kecil di tengah. Berapa banyak segitiga kecil yang terbentuk?", "pilihan": ["2", "3", "4", "5"], "jawaban": 2, "pembahasan": "JAWABAN: 4\nMenghubungkan titik tengah ketiga sisi membentuk 4 segitiga kecil di dalam segitiga besar (3 di sudut + 1 di tengah).\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,", "gambarPembahasan": "data:image/svg+xml;base64,"},
    {"id": "tg69", "pertanyaan": "Perhatikan gambar berikut. Pola warna berulang: merah, kuning, hijau, putih. Warna kotak ke-12 adalah...", "pilihan": ["Putih", "Merah", "Kuning", "Hijau"], "jawaban": 0, "pembahasan": "JAWABAN: Putih\nPola berulang setiap 4. Kotak ke-12 = 12 ÷ 4 = 3 siklus penuh, jadi kembali ke warna keempat: putih.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "deret-pola", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg70", "pertanyaan": "Perhatikan gambar berikut. Deret gambar: 2 titik, 4 titik, 6 titik. Berapa titik pada gambar ke-5?", "pilihan": ["9", "10", "12", "8"], "jawaban": 1, "pembahasan": "JAWABAN: 10\nPolanya bertambah 2 setiap gambar: 2, 4, 6, 8, 10. Gambar ke-5 = 10 titik.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "deret-pola", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg71", "pertanyaan": "Perhatikan gambar berikut. Bangun pada gambar berikut memiliki berapa sisi?", "pilihan": ["9", "6", "7", "8"], "jawaban": 3, "pembahasan": "JAWABAN: 8\nHitung sisi mengikuti arah jarum jam: ada 8 sisi, jadi bangun ini segi delapan (oktagon).\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg72", "pertanyaan": "Perhatikan gambar berikut. Berapa banyak titik sudut pada bangun berikut?", "pilihan": ["7", "4", "5", "6"], "jawaban": 2, "pembahasan": "JAWABAN: 5\nTitik sudut adalah pertemuan dua sisi. Pada segi lima ada 5 titik sudut (sama banyak dengan sisinya).\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg73", "pertanyaan": "Perhatikan gambar berikut. Deret gambar: lingkaran dalam persegi, persegi dalam segitiga, segitiga dalam lingkaran. Gambar berikutnya adalah...", "pilihan": ["Lingkaran dalam persegi", "Persegi dalam segitiga", "Segitiga dalam lingkaran", "Persegi dalam lingkaran"], "jawaban": 0, "pembahasan": "JAWABAN: Lingkaran dalam persegi\nPola berulang tiga bentuk, jadi gambar ke-4 kembali ke pola pertama: lingkaran dalam persegi.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "deret-pola", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg74", "pertanyaan": "Perhatikan gambar berikut. Berapa banyak garis diagonal pada sebuah persegi?", "pilihan": ["1", "2", "3", "4"], "jawaban": 1, "pembahasan": "JAWABAN: 2\nDiagonal menghubungkan dua sudut yang berhadapan. Pada persegi hanya ada 2 diagonal (dua pasang sudut berhadapan).\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg75", "pertanyaan": "Perhatikan gambar berikut. Gambar jam menunjukkan pukul 6:00. Sudut antara kedua jarum jam adalah...", "pilihan": ["90°", "120°", "150°", "180°"], "jawaban": 3, "pembahasan": "JAWABAN: 180°\nPukul 6:00 jarum pendek di angka 6 dan jarum panjang di angka 12, tepat berhadapan membentuk garis lurus = 180°.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg76", "pertanyaan": "Perhatikan gambar berikut. Gambar jam menunjukkan pukul 9:00. Sudut antara kedua jarum jam adalah...", "pilihan": ["180°", "60°", "90°", "120°"], "jawaban": 2, "pembahasan": "JAWABAN: 90°\nPukul 9:00 jarum pendek di angka 9 dan jarum panjang di angka 12. Selisih 3 angka × 30° = 90°.\nINGAT: Kerjakan soal gambar dengan menghitung, bukan menebak.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg77", "pertanyaan": "Perhatikan gambar berikut. Berapa banyak rusuk pada bangun kubus?", "pilihan": ["12", "16", "6", "8"], "jawaban": 0, "pembahasan": "JAWABAN: 12\nKubus punya 12 rusuk (4 di alas, 4 di atas, 4 tegak), 6 sisi, dan 8 titik sudut.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg78", "pertanyaan": "Perhatikan gambar berikut. Berapa banyak titik sudut pada bangun balok?", "pilihan": ["6", "8", "12", "16"], "jawaban": 1, "pembahasan": "JAWABAN: 8\nBalok memiliki 8 titik sudut, 12 rusuk, dan 6 sisi — sama seperti kubus, bedanya panjang rusuk tidak sama.\nINGAT: Soal hitung bangun: hitung sistematis dari bentuk terkecil ke terbesar supaya tidak ada yang terlewat.", "topik": "hitung-bangun", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg79", "pertanyaan": "Perhatikan gambar berikut. Deret gambar: 2 titik, 5 titik, 10 titik (pola n² + 1). Berapa titik pada gambar ke-4?", "pilihan": ["20", "15", "16", "17"], "jawaban": 3, "pembahasan": "JAWABAN: 17\nPolanya n² + 1: 1² + 1 = 2, 2² + 1 = 5, 3² + 1 = 10, maka gambar ke-4 = 4² + 1 = 17 titik.\nINGAT: Soal gambar: baca pola dari BARIS dan KOLOM (biasanya penambahan, perkalian, atau rotasi tetap).", "topik": "deret-pola", "gambar": "data:image/svg+xml;base64,"},
    {"id": "tg80", "pertanyaan": "Perhatikan gambar berikut. Segitiga dengan ujung menghadap ATAS diputar 180°. Ujungnya kini menghadap...", "pilihan": ["Kiri", "Atas", "Bawah", "Kanan"], "jawaban": 2, "pembahasan": "JAWABAN: Bawah\nPutaran 180° membalik arah sepenuhnya: atas menjadi bawah.\nINGAT: Cermin kiri-kanan membalik sisi kiri-kanan; cermin atas-bawah membalik atas-bawah; putar 180° membalik keduanya.", "topik": "cermin-rotasi", "gambar": "data:image/svg+xml;base64,"}
]};
